<script>

function Playlist_getCubeIdList(){
    var ret = [];
    Playlist_items.forEach(function (i){
        if (ret.indexOf(i.cubeId) == -1){
            ret.push(i.cubeId);
        }
    });
    return ret;
}

function Playlist_showItemByCubeLambda(item){
    var isPlaying = !(false === Playlist_state.cursorIntervalId);
    var magicNumber = 2;
    Playlist_state.keepPlaying += magicNumber;
    Spectrum_showWavelengthA(item.lambda_A, item.cubeId);
}

function Playlist_goDirection(dir){
    if (Playlist_items.length == 0){
        Playlist_stop();
    }
    Playlist_state.cursor = (Playlist_items.length*2 + Playlist_state.cursor + dir)  % (Playlist_items.length || 1);
    var allInSameCube = Playlist_getCubeIdList().length < 2;    
    if (allInSameCube){
        Playlist_showItemByCubeLambda(Playlist_items[Playlist_state.cursor]);
    }else{
        Playlist_showItem(Playlist_state.cursor);
    }    
    Playlist_drawCursor();
}

function Playlist_next(){
    Playlist_goDirection(1);
}
function Playlist_prev(){
    Playlist_goDirection(-1);
}

function Playlist_getIntervalInput(){
    return document.getElementById("playlist-interval");
}

function Playlist_getIntervalLength(num = false){
    var def = 75;
    var minv = 15;
    var maxv = 1000;
    if (false === num){
        var v = Playlist_getIntervalInput().value;
    }else{
        var v = num;
    }
    v = parseFloat(v);
    if (v === v){
        // number
    }else{
        v = def;
    }
    v = Math.min(maxv, v);
    v = Math.max(minv, v);
    return v;
}

function Playlist_play(){
    Playlist_stop();
    Playlist_state.cursorIntervalId = setInterval(function (){
        Playlist_next();
    }, Playlist_getIntervalLength());
}
function Playlist_stop(){
    if (false === Playlist_state.cursorIntervalId){
        // nothing to remove
    }else{
        clearInterval(Playlist_state.cursorIntervalId);
        Playlist_state.cursorIntervalId = false;
    }    
}
function Playlist_applyNewInterval(){
    if (false === Playlist_state.cursorIntervalId){
        // no interval has been running
    }else{    
        clearInterval(Playlist_state.cursorIntervalId);
        Playlist_state.cursorIntervalId = setInterval(function (){
            Playlist_next();
        }, Playlist_getIntervalLength());
    }
}

function Playlist_multiplyInterval(m){
    var i = Playlist_getIntervalLength();
    i *= m;
    Playlist_getIntervalInput().value = Playlist_getIntervalLength(Math.round(i));
    Playlist_applyNewInterval();
}

function Playlist_setIntervalInput(){
    Playlist_getIntervalInput().value = Playlist_getIntervalLength();
}


function Playlist_getMasterElement(){
    var e = document.getElementById("playlist-wrapper");
    return e;
}
function Playlist_getTheTable(){
    var e = document.getElementById("playlist-table");
    return e;
}

function Playlist_createBlankItem(){
    var i = {        
        cubeId: "string",
        src: "string",
        lambda_A: 123456,
        caption: "string",
        partialState: { o: "object"},
        pixelShift: 123456

    };
    return i;
}
function Playlist_isItem(i){
    var ret = false;
    try {
        var reference = Playlist_createBlankItem();
        ret = Object.keys(i).sort().join('?') == Object.keys(reference).sort().join('?');
    }catch(err){
        //
    }
    return ret;
}

function Playlist_importFromJSON(jsonString){
    var j = false;
    
    try {
        if (typeof jsonString !== "string"){
            jsonString = JSON.stringify(jsonString);
        }
        j = JSON.parse(jsonString);
        j.items.forEach(function (i){
            if (!Playlist_isItem(i)){
                j = false;
            }
        });        
    }catch(err){
        j = false;
    }
    if (j){
        Playlist_items = JSON.parse(JSON.stringify(j.items));
    }
    Playlist_render();
}

function Playlist_exportToJSON(){
    return JSON.stringify({ title: "current view", items: Playlist_items });
}



function Playlist_getCurrentSliceTwin(){
    var id = 'current-slice-twin';
    var ret = document.getElementById(id);
    if (!ret){
        ret = document.createElement("img");
        ret.id = id;
        var t = document.getElementById("current-slice");
        ret.style.width = t.style.width;
        ret.style.height = t.style.height;
        t.parentNode.appendChild(ret);
    }
    return ret;
}
function Playlist_showTwin(itemIndex){
    var list = document.getElementsByClassName("brightness-and-gamma-display-wrapper");
    for (var i=0; i<list.length; i++){
        list[i].style.display = "none";
    }
    document.getElementById("current-slice").style.display = "none";
    document.getElementById("current-slice-display-notes").style.display = "none";
    var t = Playlist_getCurrentSliceTwin();        
    t.style.display = "";
    ImageGeneric_applyDisplayFiltersFromPartialState(t, Playlist_items[itemIndex].partialState);
    t.src = Url_proxifyIfNeeded(Playlist_items[itemIndex].src);
    return t;
}
function Playlist_showItem(itemIndex){
    var v = Playlist_items.length > 0;
    Playlist_setVisibility(v);    
    if (v){
        var t = Playlist_showTwin(itemIndex);        
        var caption = "Playlist item: "+parseFloat(Playlist_items[itemIndex].lambda_A).toFixed(2)+'&#8491; '+Playlist_items[itemIndex].caption;
        document.getElementById("current-slice-subtitle").innerHTML = caption;
    }
    Playlist_drawCursor(itemIndex);
};
function Playlist_setVisibility(v){
    Playlist_getMasterElement().style.display = v ? "" : "none";
    if (!v){
        Playlist_stop();
        Playlist_hideTwin();
    }    
}   
function Playlist_hideTwin(){
    Playlist_getCurrentSliceTwin().style.display = "none";        
    document.getElementById("current-slice").style.display = "";
    document.getElementById("current-slice-display-notes").style.display = "";
    var subtitle = document.getElementById("current-slice-subtitle");    
    subtitle.innerHTML =  subtitle.getAttribute("data-cube-slice-caption") || "";
    var list = document.getElementsByClassName("brightness-and-gamma-display-wrapper");
    for (var i=0; i<list.length; i++){
        list[i].style.display = "";
    }
}
function Playlist_close(){    
    Playlist_setVisibility(false);
}



function Playlist_moveItemAtIndex(i, d){
    var i1 = i;
    var i2 = i+d;
    if (i1 < 0){
        return ;
    }
    if (i2 < 0){
        return ;
    }
    if (i1 >= Playlist_items.length){
        return ;
    }
    if (i2 >= Playlist_items.length){
        return ;
    }

    var dummy = Playlist_items[i1];
    Playlist_items[i1] = Playlist_items[i2];
    Playlist_items[i2] = dummy;
}
function Playlist_removeItemAtIndex(itemIndex){
    var itemCount = 1;
    Playlist_items.splice(itemIndex, itemCount);
};
function Playlist_render(){
    var columns = [
        {
            header: 'show slice<br>as added',
            shower: function (item, parent, itemIndex, itemCount){
                var b = document.createElement("button");
                b.innerHTML = '&larr;';
                b.addEventListener("click", function (){
                    Playlist_showItem(itemIndex);
                });
                parent.appendChild(b);
            },
        },
        {
            header: 'show slice<br>in its cube',
            shower: function (item, parent, itemIndex, itemCount){
                var b = document.createElement("button");
                b.innerHTML = '&#8615;';
                b.addEventListener("click", function (){
                    // show cube slice by wavelength and preferred cube
                    Spectrum_showWavelengthA(item.lambda_A, item.cubeId);
                });
                parent.appendChild(b);
            },            
        },
        {
            header: '&lambda; [&#8491;]',
            shower: function (item, parent, itemIndex, itemCount){
                var span = document.createElement("span");
                span.innerHTML = parseFloat(item.lambda_A).toFixed(2);
                span.style.cursor = "pointer";
                span.addEventListener("click", function (){
                    // show cube slice by wavelength and preferred cube
                    Spectrum_showWavelengthA(item.lambda_A, item.cubeId);
                    Playlist_drawCursor(itemIndex);
                });
                parent.appendChild(span);
            },
        },
        {
            header: 'caption',
            shower: function (item, parent, itemIndex, itemCount){
                var i = document.createElement("input");
                i.type="text";
                i.value = item.caption;
                i.style.width = "100px";
                ["keyup", "keypress", "keydown", "mousemove", "change", "paste"].forEach(function (ev){
                    i.addEventListener(ev, function (e){
                        item.caption = i.value;
                    });
                });
                parent.appendChild(i);
            },
        },
        {
            header: '',
            shower: function (item, parent, itemIndex, itemCount){
                if (0 == itemIndex){
                    // don't show the up button
                    return ;
                }
                var b = document.createElement("button");
                b.innerHTML = '&#x25B2;';
                b.addEventListener("click", function (){
                    Playlist_moveItemAtIndex(itemIndex, -1);
                    Playlist_render();
                });
                parent.appendChild(b);
            },
        },
        {
            header: '',
            shower: function (item, parent, itemIndex, itemCount){
                if (itemCount-1 == itemIndex){
                    // don't show the down button
                    return ;
                }
                var b = document.createElement("button");
                b.innerHTML = '&#x25BC;';
                b.addEventListener("click", function (){
                    Playlist_moveItemAtIndex(itemIndex, 1);
                    Playlist_render();
                });
                parent.appendChild(b);
            },
        },
        {
            header: '<button onclick="Playlist_emptify()">X</button>',
            shower: function (item, parent, itemIndex, itemCount){
                var b = document.createElement("button");
                b.innerHTML = 'X';
                b.addEventListener("click", function (){
                    Playlist_removeItemAtIndex(itemIndex);
                    Playlist_render();
                });
                parent.appendChild(b);
            },
        },
        {
            header: 'url',
            shower: function (item, parent, itemIndex, itemCount){
                var a = document.createElement("a");
                a.href = Url_proxifyIfNeeded(item.src);
                a.target = "_blank";
                a.innerHTML = "img";
                parent.appendChild(a);
            },
        },
    ];
    var t = Playlist_getTheTable();
    t.innerHTML = "";
    var hasHeader = false;
    Playlist_items.forEach(function (item, itemIndex){
        var tr;
        var td;
        if (!hasHeader){
            tr = document.createElement("tr");
            columns.forEach(function (c){
                td = document.createElement("td");
                td.innerHTML = c.header;
                td.style.backgroundColor = "#eee";
                tr.appendChild(td);
            })
            t.appendChild(tr);
            hasHeader = true;
        }
        tr = document.createElement("tr");
        tr.setAttribute("data-row-index", itemIndex);
        tr.className = "playlist-item-row";
        columns.forEach(function (c){
            td = document.createElement("td");
            c.shower(item, td, itemIndex, Playlist_items.length);
            tr.appendChild(td);
        })
        t.appendChild(tr);
    });
    Playlist_drawCursor();
    Playlist_setVisibility(Playlist_items.length > 0);
    Playlist_exportToJSONWrapper();
} 

function Playlist_getTheRows(){
    var tr = Playlist_getTheTable().getElementsByClassName("playlist-item-row");
    var ret = [];
    for (var i=0; i<tr.length; i++){
        ret.push(tr[i]);
    }
    return ret;
}


function Playlist_drawCursor(setCursorToIndex = false){
    if (0 == Playlist_items.length){
        return ;
    }
    if (false === setCursorToIndex){
        setCursorToIndex = Playlist_state.cursor;
    }
    if (-1 === setCursorToIndex){
        setCursorToIndex = Playlist_items.length-1;
    }    
    Playlist_state.cursor = setCursorToIndex;
    Playlist_state.cursor = (Playlist_items.length*2 + Playlist_state.cursor + 0)  % (Playlist_items.length || 1);

    Playlist_getTheRows().forEach(function (tr){
        var selected = tr.getAttribute("data-row-index") == Playlist_state.cursor;
        var className = "selected-playlist-item";
        var k = tr.className+'';
        k = k.split(className).join(" ");
        if (selected){
            k+=' '+className;
        }
        k = k.trim();
        tr.className = k;
    });
}

function Playlist_truncate(){
    Playlist_stop();
    Playlist_items = [];
    Playlist_setVisibility(Playlist_items.length > 0);
}
function Playlist_emptify(){
    Playlist_stop();
    Playlist_items = [];
    Playlist_render();
}
function Playlist_addCurrentCubeSlice(halfWidth){
    halfWidth = halfWidth || 0;    
    var i = document.getElementById("current-slice");
    var cubeId = i.getAttribute("data-current-cube-id"); 
    var pixelShift = parseFloat(OnImage_getThePixelShiftEditor(cubeId).value);

    var pixelPos = [pixelShift];
    for (var i=1; i<=halfWidth; i++){
        pixelPos.push(pixelShift+i);
        pixelPos.unshift(pixelShift-i);
    }
    var ps = createPartialStateWithDisplayFilters();    
    var cpx = OnImage_getCwl_px(cubeId);

    pixelPos.forEach(function (pixelShift){        
        var lambda_A = OnImage_pixelShiftToWavelength_A(cubeId, pixelShift);
        var chemical = OnImageGeneric_wavelengthToChemicalLabel(lambda_A);                  
        var list = OnImage_getImageList(cubeId, pixelShift);
        if (list.length > 0){
            var frameSrc = Url_deproxify(list[0]);
            var playlistItem = {
                cubeId: cubeId,
                src: frameSrc,
                lambda_A: lambda_A,
                caption: chemical,
                partialState: ps,
                pixelShift: pixelShift
            };
            Playlist_items.push(playlistItem);
            console.log("playlistItem", playlistItem);
        }
    });
    Playlist_drawCursor(-1);
    Playlist_render();
}

function Playlist_exportToJSONWrapper(){
    var t = document.getElementById("playlist-stringified");
    t.value = Playlist_exportToJSON();
};

